-- Sapar Trade — QR для оплаты при доставке (Kaspi QR, Halyk QR). Картинки показывает водитель; владелец меняет их в Настройках.
CREATE TABLE payment_qr (
  method     text PRIMARY KEY CHECK (method IN ('kaspi','halyk')),
  image      text NOT NULL CHECK (image LIKE 'data:image/%'),
  updated_by integer REFERENCES users(id),
  updated_at timestamptz NOT NULL DEFAULT now()
);
-- Первые QR владельца (ИП Сапар), присланные 19.11.2026
INSERT INTO payment_qr(method, image) VALUES
  ('kaspi', 'data:image/jpeg;base64,'),
  ('halyk', 'data:image/jpeg;base64,');
